import unittest
from candidate import largest_prime_factor

class TestLargestPrimeFactor(unittest.TestCase):
    def test_normal_case_small_prime_factor(self):
        self.assertEqual(largest_prime_factor(13195), 29)

    def test_normal_case_large_prime_factor(self):
        self.assertEqual(largest_prime_factor(600851475143), 6857)

    def test_normal_case_small_number(self):
        self.assertEqual(largest_prime_factor(12), 3)

    def test_normal_case_even_number(self):
        self.assertEqual(largest_prime_factor(2048), 2)

    def test_boundary_condition_minimum_input(self):
        self.assertEqual(largest_prime_factor(2), 2)

    def test_boundary_condition_prime_number(self):
        with self.assertRaises(AssertionError):
            largest_prime_factor(17)  # Should not be called as per problem statement

    def test_edge_case_small_prime_product(self):
        self.assertEqual(largest_prime_factor(15), 5)

    def test_edge_case_square_of_prime(self):
        self.assertEqual(largest_prime_factor(49), 7)

    def test_edge_case_highly_composite_number(self):
        self.assertEqual(largest_prime_factor(13195 * 2), 29)

    def test_type_error_integer_input(self):
        with self.assertRaises(TypeError):
            largest_prime_factor("13195")

    def test_type_error_non_integer_input(self):
        with self.assertRaises(TypeError):
            largest_prime_factor([13195])

    def test_none_input(self):
        with self.assertRaises(TypeError):
            largest_prime_factor(None)

    def test_negative_input(self):
        with self.assertRaises(ValueError):
            largest_prime_factor(-13195)

    def test_zero_input(self):
        with self.assertRaises(ValueError):
            largest_prime_factor(0)

    def test_large_number(self):
        self.assertEqual(largest_prime_factor(99999999999999999999), 99999999999999999999 // 2)

    def test_duplicate_prime_factors(self):
        self.assertEqual(largest_prime_factor(100), 5)
